static_assert(::std::bit_cast<VkSubpassDescriptionFlags>(subpass_description2<>::flags_type{.enable_legacy_dithering = 1}) == VK_SUBPASS_DESCRIPTION_ENABLE_LEGACY_DITHERING_BIT_EXT);
