[[nodiscard]] auto allocate_command_buffers(VkDevice device, Expression&& info, ::std::span<VkCommandBuffer> produced, ::std::nothrow_t) noexcept
	-> ::std::expected<void, ::VkResult>
{
	decltype(auto) storage = ::vkfu::evaluate(::std::forward<Expression>(info));
	auto const result = ::vkAllocateCommandBuffers(device, ::std::addressof(::vkfu::unpack(storage)), produced.data());
	if (result != ::VK_SUCCESS)
	{
		return ::std::unexpected{result};
	}
	return {};
}

